pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address attackerAddr, uint256 amt) public {
        vm.assume(attackerAddr != address(0));
        vm.assume(attackerAddr != address(c));

        Reverter rev = new Reverter();

        address[] memory tos = new address[](1);
        uint[] memory vs = new uint[](1);
        tos[0] = address(0x1234);
        vs[0] = amt;

        bool ok;
        try c.transfer(address(rev), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
